-- RN Master native-format/case-study pilot import. Preserves matrix, cloze, highlight, bow-tie, SATA and MC formats.
begin;
insert into public.question_case_studies(id,title,case_stem,initial_data,source_note) values('RNMaster-Set22-Case','RN Master Set 22 unfolding case study','A 9-month-old infant is brought to the pediatric emergency department by a parent. The infant has had a fever for 18 hours and has become increasingly irritable and difficult to console. The infant''s immunizations are behind schedule. Nurses'' notes, 2100: Infant cries more when picked up and held (paradoxical irritability) and has a high-pitched cry. Anterior fontanel is bulging while the infant is calm and upright. Vomited twice. Refusing bottle; 1 wet diaper in 8 hours. A few nonblanching purple spots on the lower legs. Capillary refill 3 seconds. Vital signs: T 103.6°F (39.8°C) rectal, HR 176/min, RR 40/min, BP 80/44 mm Hg, SpO2 96% on room air. Weight 8.5 kg. Laboratory results: WBC 22,000/mm³, blood glucose 72 mg/dL. Lumbar puncture is planned.','{}'::jsonb,'User-provided RN master case study.') on conflict(id) do update set case_stem=excluded.case_stem,updated_at=now();
insert into public.question_case_studies(id,title,case_stem,initial_data,source_note) values('RNMaster-Set23-Case','RN Master Set 23 unfolding case study','A 67-year-old client arrived at the emergency department 14 hours after the onset of chest pain and was diagnosed with a large anterior ST-elevation myocardial infarction. The client is awaiting emergency cardiac catheterization. Nurses'' notes, 0400: Newly confused and restless. Skin cool, clammy, and mottled on the knees. Crackles halfway up both lung fields. Jugular venous distention at 45°. New S3 gallop. Urine output 10 mL/hr for the past 2 hours. Vital signs: HR 118/min, BP 78/50 mm Hg (MAP 59), RR 30/min, SpO2 88% on 4 L/min nasal cannula, T 98.0°F (36.7°C). Laboratory and diagnostic results: lactate 4.2 mmol/L (0.5–2.0), creatinine 1.8 mg/dL (baseline 1.0), troponin markedly elevated. Bedside echocardiogram: left ventricular ejection fraction 20% with a large area of anterior wall akinesis.','{}'::jsonb,'User-provided RN master case study.') on conflict(id) do update set case_stem=excluded.case_stem,updated_at=now();
insert into public.question_case_studies(id,title,case_stem,initial_data,source_note) values('RNMaster-Set24-Case','RN Master Set 24 unfolding case study','A 46-year-old client with a history of heavy daily alcohol use arrives at the emergency department with severe epigastric pain that began 12 hours ago and radiates to the back. The client reports nausea and has vomited several times. The last drink was 10 hours ago. Nurses'' notes, 1300: Pain rated 9/10, slightly relieved by sitting up and leaning forward. Abdomen distended with guarding; bowel sounds hypoactive. Mucous membranes dry. Client reports tingling around the mouth. Vital signs: T 100.6°F (38.1°C), HR 124/min, RR 26/min, BP 94/58 mm Hg, SpO2 93% on room air. Laboratory results: lipase 2,400 units/L (0–160), glucose 248 mg/dL, calcium 7.6 mg/dL (8.6–10.2), WBC 16,800/mm³, hematocrit 50% (37–47), BUN 34 mg/dL, creatinine 1.4 mg/dL (baseline 0.9), triglycerides normal.','{}'::jsonb,'User-provided RN master case study.') on conflict(id) do update set case_stem=excluded.case_stem,updated_at=now();
insert into public.question_case_studies(id,title,case_stem,initial_data,source_note) values('RNMaster-Set25-Case','RN Master Set 25 unfolding case study','A 24-year-old client is brought to the emergency department by a roommate after telling friends by text that they "took a whole bottle" of extra-strength acetaminophen about 18 hours ago. The client has been vomiting since this morning. Nurses'' notes, 1400: Drowsy but arousable; oriented to person only. Flapping tremor of the hands when the arms are extended (asterixis). Right upper quadrant tenderness. Sclera slightly yellow. The client says, "I just wanted everything to stop." Vital signs: T 99.0°F (37.2°C), HR 108/min, RR 20/min, BP 106/64 mm Hg, SpO2 97% on room air. Weight 60 kg. Laboratory results: serum acetaminophen 180 mcg/mL at an estimated 18 hours after ingestion (well above the treatment line), AST 4,200 units/L, ALT 5,100 units/L, INR 3.2, total bilirubin 4.1 mg/dL, glucose 58 mg/dL, ammonia elevated, creatinine 1.6 mg/dL.','{}'::jsonb,'User-provided RN master case study.') on conflict(id) do update set case_stem=excluded.case_stem,updated_at=now();
insert into public.question_case_studies(id,title,case_stem,initial_data,source_note) values('RNMaster-Set26-Case','RN Master Set 26 unfolding case study','A 38-year-old farmworker is brought to the emergency department about 1 hour after being sprayed with an organophosphate insecticide while working in a field. The client''s clothing is damp and has a strong chemical odor. Nurses'' notes, 1100: Anxious and intermittently confused. Excessive drooling, tearing, and sweating. Vomited twice and had diarrhea and urinary incontinence. Pupils pinpoint. Visible muscle twitching in the arms and chest. Diffuse wheezing with copious, bubbling airway secretions. Vital signs: HR 44/min, BP 92/56 mm Hg, RR 30/min, SpO2 86% on room air, T 98.8°F (37.1°C).','{}'::jsonb,'User-provided RN master case study.') on conflict(id) do update set case_stem=excluded.case_stem,updated_at=now();
insert into public.question_case_studies(id,title,case_stem,initial_data,source_note) values('RNMaster-Set27-Case','RN Master Set 27 unfolding case study','A 34-year-old client with Graves'' disease stopped taking methimazole 2 months ago because "I felt better." The client has had a cough and fever for 3 days and is brought in by a partner for increasing agitation. Nurses'' notes, 1900: Restless, agitated, and intermittently disoriented. Profuse sweating. Fine tremor of the hands. Reports several loose stools daily. Bulging eyes (exophthalmos) and a diffusely enlarged thyroid with an audible bruit. Raised, thickened skin on both shins. Crackles in the right lower lobe. Vital signs: T 104.9°F (40.5°C), HR 168/min and irregularly irregular (atrial fibrillation), RR 28/min, BP 150/60 mm Hg, SpO2 93% on room air. Laboratory results: TSH undetectable, free T4 markedly elevated, glucose 180 mg/dL, WBC 15,200/mm³, AST and ALT mildly elevated. Chest x-ray: right lower lobe infiltrate.','{}'::jsonb,'User-provided RN master case study.') on conflict(id) do update set case_stem=excluded.case_stem,updated_at=now();
insert into public.question_case_studies(id,title,case_stem,initial_data,source_note) values('RNMaster-Set28-Case','RN Master Set 28 unfolding case study','A 3-year-old is brought to the emergency department after being found face-down in a backyard pool. The estimated submersion time is about 2 minutes. A parent began rescue breathing and compressions; the child coughed up water and began breathing before EMS arrived. There was no diving or fall. Nurses'' notes, 1630: Drowsy but opens eyes and responds to voice. Coughing frothy, pink-tinged sputum. Crackles in both lung fields. Subcostal and intercostal retractions. Clothing wet. Skin cool and mottled on the arms and legs; shivering. Vital signs: T 95.0°F (35.0°C) rectal, HR 148/min, RR 44/min, BP 92/58 mm Hg, SpO2 89% on room air. Laboratory results: blood glucose 160 mg/dL, sodium 138 mEq/L. Chest x-ray: patchy bilateral infiltrates.','{}'::jsonb,'User-provided RN master case study.') on conflict(id) do update set case_stem=excluded.case_stem,updated_at=now();
insert into public.question_case_studies(id,title,case_stem,initial_data,source_note) values('RNMaster-Set29-Case','RN Master Set 29 unfolding case study','A 71-year-old client with atrial fibrillation stopped taking apixaban 3 weeks ago because of cost. The client arrives at the emergency department reporting sudden, severe pain in the left leg that began 2 hours ago while watching television. Nurses'' notes, 2000: Left foot and lower leg are pale and cold to the touch. Left pedal and popliteal pulses absent by palpation, with no Doppler signal at the dorsalis pedis or posterior tibial arteries. Reports numbness of the left toes. Weak dorsiflexion of the left foot. Capillary refill in the left toes greater than 5 seconds. Right leg warm with palpable pulses. No leg swelling. Vital signs: HR 112/min and irregularly irregular, BP 148/86 mm Hg, RR 20/min, SpO2 97% on room air, T 98.4°F (36.9°C). Laboratory results: creatinine 1.0 mg/dL, potassium 4.3 mEq/L, creatine kinase 280 units/L (mildly elevated).','{}'::jsonb,'User-provided RN master case study.') on conflict(id) do update set case_stem=excluded.case_stem,updated_at=now();
insert into public.question_case_studies(id,title,case_stem,initial_data,source_note) values('RNMaster-Set30-Case','RN Master Set 30 unfolding case study','A 9-year-old is admitted for abdominal pain that began around the umbilicus yesterday and moved to the right lower quadrant overnight. The child has vomited twice and refuses to eat. Nurses'' notes, 0800: Lying still with knees flexed. Tenderness and rebound tenderness at McBurney''s point. T 101.8°F (38.8°C), HR 118/min, BP 104/66 mm Hg, RR 22/min. WBC 16,400/mm³. Ultrasound shows an enlarged, noncompressible appendix. NPO; IV fluids running. Surgery is scheduled for later this morning. Nurses'' notes, 1030: The child says, "My tummy suddenly feels better." Twenty minutes later, the child is lethargic, the abdomen is diffusely rigid and distended, and bowel sounds are absent. T 103.3°F (39.6°C), HR 146/min, BP 86/50 mm Hg, RR 30/min, capillary refill 4 seconds.','{}'::jsonb,'User-provided RN master case study.') on conflict(id) do update set case_stem=excluded.case_stem,updated_at=now();
do $$
declare r record; qid uuid; qvid uuid; optrec record; n int; keyarr text[]; kc int;
begin
for r in select * from (values
('Set22-RN-20','Physiological Adaptation','Case study: Recognize cues','highlight','Highlight (circle) the findings that require immediate follow-up.','','','A bulging fontanel and high-pitched cry suggest increased intracranial pressure. Nonblanching spots with fever suggest meningococcemia. Tachycardia, low BP, and oliguria indicate early shock. SpO2 and glucose are acceptable.','Integrated','Adult Health','{"segments":[{"id":"s1","text":"Bulging anterior fontanel","correct":true},{"id":"s2","text":"High-pitched cry and paradoxical irritability","correct":true},{"id":"s3","text":"Nonblanching purple spots on the legs","correct":true},{"id":"s4","text":"T 103.6°F (39.8°C)","correct":false},{"id":"s5","text":"HR 176/min with BP 80/44 mm Hg","correct":true},{"id":"s6","text":"1 wet diaper in 8 hours","correct":false},{"id":"s7","text":"SpO2 96% on room air","correct":false},{"id":"s8","text":"Blood glucose 72 mg/dL","correct":false}]}','RNMaster-Set22-Case','1'),
('Set22-RN-21','Physiological Adaptation','Case study: Analyze cues','matrix_grid','For each finding, indicate whether it primarily reflects meningeal inflammation or increased ICP, or systemic infection with poor perfusion. Systemic Meningeal infl','','','Meningeal/ICP: bulging fontanel, high-pitched cry, paradoxical irritability. Systemic: petechiae/purpura, tachycardia with hypotension, delayed capillary refill. Infants often lack classic neck stiffness. A bulging fontanel, high-pitched cry, and irritability when handled are key signs. Petechial or purpuric rash and poor perfusion indicate bacteremia and possible septic shock.','Integrated','Adult Health','{"columns":[{"id":"c1","label":"infection/poor"}],"rows":[{"id":"r1","label":"Bulging anterior fontanel","correct":"c1"},{"id":"r2","label":"High-pitched cry","correct":"c1"},{"id":"r3","label":"Paradoxical irritability","correct":"c1"},{"id":"r4","label":"Nonblanching purple spots","correct":"c1"},{"id":"r5","label":"HR 176/min with BP 80/44 mm Hg","correct":"c1"},{"id":"r6","label":"Capillary refill 3 seconds","correct":"c1"}]}','RNMaster-Set22-Case','2'),
('Set22-RN-22','Physiological Adaptation','Case study: Prioritize hypotheses','cloze_dropdown','Complete the sentence by choosing from the lists of options. The infant is most likely experiencing ___1___ with ___2___.','','','septic shock Fever, signs of increased ICP, vomiting, and a nonblanching rash in an underimmunized infant indicate bacterial meningitis, possibly meningococcal. Hypotension and poor perfusion in a child indicate shock. Low BP is a late sign in children.','Integrated','Adult Health','{"blanks":[{"id":"b1","options":["bacterial meningitis","viral gastroenteritis","teething","roseola"],"correct":"bacterial meningitis"},{"id":"b2","options":["early septic shock","simple dehydration only","an allergic reaction","normal fever response"],"correct":"early septic shock"}]}','RNMaster-Set22-Case','3'),
('Set22-RN-23','Management of Care','Case study: Generate solutions','multiple_response','Which interventions does the nurse anticipate? Select all that apply. ☐','Initiate droplet precautions ☐|Obtain blood cultures and start IV antibiotics as soon as possible, without delaying for the lumbar puncture ☐|Administer an isotonic fluid bolus (such as 20 mL/kg) as prescribed and reassess ☐|Implement seizure precautions ☐|Monitor intake, output, and serum sodium ☐|Delay antibiotics until CSF results are available ☐|Give aspirin for fever','A,B,C,D,E','Bacterial meningitis requires droplet precautions for the first 24 hours of antibiotics and immediate antibiotics (with dexamethasone in some cases). Shock is treated with fluid boluses. Seizures and SIADH are common complications. Delaying antibiotics worsens outcomes, and aspirin is avoided in children.','Integrated','Management of Care','{}','RNMaster-Set22-Case','4'),
('Set22-RN-24','Pharmacological and Parenteral Therapies','Case study: Take action','single_best_answer','IV access has been established, and blood cultures have been drawn. The lumbar puncture will be delayed while the infant is stabilized. What should the nurse do next?','Wait for the lumbar puncture before giving antibiotics|Administer the prescribed IV antibiotics now|Give oral antibiotics|Start a maintenance IV fluid rate only','B','In suspected bacterial meningitis, antibiotics should not be delayed for the lumbar puncture, especially when the procedure must be postponed. Each hour of delay increases the risk of death and neurological damage.','Integrated','Pharmacology','{}','RNMaster-Set22-Case','5'),
('Set22-RN-25','Physiological Adaptation','Case study: Evaluate outcomes','matrix_grid','Forty-eight hours later, the nurse reassesses the infant. For each finding, indicate whether it shows improvement or requires follow-up. Requires','','','Improved: temperature, HR/BP, soft fontanel, wet diapers. Follow-up: hyponatremia with low urine output (possible SIADH), absent startle response (possible hearing loss). Normalizing temperature, perfusion, fontanel, and urine output show response. Hyponatremia with low urine output suggests SIADH. Sensorineural hearing loss is a common complication of bacterial meningitis, so hearing screening is recommended. Answers: Set 23: Mixed Review 6','Integrated','Adult Health','{"columns":[{"id":"c1","label":"Improved"}],"rows":[{"id":"r1","label":"T 99.4°F (37.4°C)","correct":"c1"},{"id":"r2","label":"HR 130/min, BP 94/58 mm Hg","correct":"c1"},{"id":"r3","label":"Fontanel soft and flat","correct":"c1"},{"id":"r4","label":"4 wet diapers in 8 hours","correct":"c1"},{"id":"r5","label":"Serum sodium 128 mEq/L with decreasing urine output","correct":"c1"},{"id":"r6","label":"No startle response to loud noises","correct":"c1"}]}','RNMaster-Set22-Case','6'),
('Set23-RN-20','Physiological Adaptation','Case study: Recognize cues','highlight','Highlight (circle) the findings that require immediate follow-up.','','','These findings show inadequate cardiac output with poor organ perfusion (brain, skin, kidneys) and pulmonary congestion from left ventricular failure. The temperature is normal.','Integrated','Adult Health','{"segments":[{"id":"s1","text":"New confusion and restlessness","correct":true},{"id":"s2","text":"Cool, clammy, mottled skin","correct":true},{"id":"s3","text":"BP 78/50 mm Hg (MAP 59)","correct":false},{"id":"s4","text":"Urine output 10 mL/hr","correct":true},{"id":"s5","text":"Crackles halfway up both lungs","correct":true},{"id":"s6","text":"SpO2 88% on 4 L/min","correct":true},{"id":"s7","text":"Lactate 4.2 mmol/L","correct":true},{"id":"s8","text":"Temperature 98.0°F","correct":false}]}','RNMaster-Set23-Case','1'),
('Set23-RN-21','Physiological Adaptation','Case study: Analyze cues','matrix_grid','For each finding, indicate whether it is more consistent with cardiogenic shock or hypovolemic shock. Cardiogenic   Hypovolemic Finding','','','Cardiogenic: JVD, crackles, S3, elevated wedge pressure. Hypovolemic: flat neck veins, hemorrhage with clear lungs. Both types cause hypotension and poor perfusion. In cardiogenic shock, the pump fails and fluid backs up (high filling pressures). In hypovolemic shock, the circulating volume is low. Distinguishing them determines whether fluids help or harm.','Integrated','Adult Health','{"columns":[{"id":"c1","label":"shock"}],"rows":[{"id":"r1","label":"Jugular venous distention","correct":"c1"},{"id":"r2","label":"Crackles in the lungs","correct":"c1"},{"id":"r3","label":"New S3 gallop","correct":"c1"},{"id":"r4","label":"Flat neck veins","correct":"c1"},{"id":"r5","label":"Elevated pulmonary artery wedge pressure","correct":"c1"},{"id":"r6","label":"Recent hemorrhage with clear lungs","correct":"c1"}]}','RNMaster-Set23-Case','2'),
('Set23-RN-22','Physiological Adaptation','Case study: Prioritize hypotheses','cloze_dropdown','Complete the sentence by choosing from the lists of options. The client is experiencing ___1___ caused by ___2___.','','','Delayed presentation increases the risk.','Integrated','Adult Health','{"blanks":[{"id":"b1","options":["cardiogenic shock","septic shock","anaphylactic shock","neurogenic shock"],"correct":"cardiogenic shock"},{"id":"b2","options":["left ventricular pump failure from an extensive anterior MI","bacterial infection","an allergic reaction","spinal cord injury"],"correct":"left ventricular pump failure from an extensive anterior MI"}]}','RNMaster-Set23-Case','3'),
('Set23-RN-23','Management of Care','Case study: Generate solutions','multiple_response','Which interventions does the nurse anticipate? Select all that apply. ☐','Emergency coronary revascularization (PCI) ☐|Norepinephrine infusion to maintain MAP of at least 65 mm Hg ☐|Inotropic support such as dobutamine ☐|Preparation for mechanical circulatory support (such as an intra-aortic balloon pump or percutaneous ventricular assist device) ☐|Oxygen and ventilatory support as needed ☐|1 L 0.9% sodium chloride bolus over 30 minutes ☐|IV metoprolol to slow the heart rate','A,B,C,D,E','Restoring coronary blood flow is the definitive treatment. Vasopressors, inotropes, and mechanical support maintain perfusion, and respiratory support treats hypoxemia. Large fluid boluses worsen pulmonary congestion, and beta blockers further reduce contractility in shock.','Integrated','Management of Care','{}','RNMaster-Set23-Case','4'),
('Set23-RN-24','Pharmacological and Parenteral Therapies','Case study: Take action','single_best_answer','The client is receiving norepinephrine at 0.05 mcg/kg/min. The titration protocol targets a MAP of at least 65 mm Hg, and the current MAP is 59. The infusion site is intact. What should the nurse do?','Stop the norepinephrine|Increase the norepinephrine per the titration protocol and recheck BP frequently|Give a 2-L fluid bolus|Wait 2 hours and recheck','B','Vasopressors are titrated per protocol to reach target perfusion pressure, with frequent BP monitoring, ideally by arterial line. The nurse also checks the IV site because extravasation can cause tissue necrosis.','Integrated','Pharmacology','{}','RNMaster-Set23-Case','5'),
('Set23-RN-25','Physiological Adaptation','Case study: Evaluate outcomes','matrix_grid','After PCI and placement of a femoral mechanical support device, the nurse reassesses the client. For each finding, indicate whether it shows the treatment was effective or requires immediate follow-up. Requires','','','Effective: MAP 72, urine output 45, lactate 1.8, alert. Follow-up: limb ischemia on the device side, norepinephrine extravasation. Improved MAP, urine output, lactate, and mentation show restored perfusion. A cool, pale limb distal to a femoral device suggests ischemia. Blanching at a vasopressor site suggests extravasation, which requires stopping the infusion at that site and giving the antidote (such as phentolamine) per protocol. Answers: Set 24: Mixed Review 7','Integrated','Adult Health','{"columns":[{"id":"c1","label":"Effective"}],"rows":[{"id":"r1","label":"MAP 72 mm Hg","correct":"c1"},{"id":"r2","label":"Urine output 45 mL/hr","correct":"c1"},{"id":"r3","label":"Lactate 1.8 mmol/L","correct":"c1"},{"id":"r4","label":"Alert and oriented","correct":"c1"}]}','RNMaster-Set23-Case','6'),
('Set24-RN-20','Physiological Adaptation','Case study: Recognize cues','highlight','Highlight (circle) the findings that require immediate follow-up.','','','Hypovolemia from third-spacing (tachycardia, hypotension, hemoconcentration, rising creatinine), hypocalcemia, hyperglycemia, falling oxygenation, and severe pain all need prompt treatment. Normal triglycerides help rule out hypertriglyceridemia as the cause.','Integrated','Adult Health','{"segments":[{"id":"s1","text":"HR 124/min with BP 94/58 mm Hg","correct":true},{"id":"s2","text":"Hematocrit 50%","correct":true},{"id":"s3","text":"Calcium 7.6 mg/dL with perioral tingling","correct":true},{"id":"s4","text":"SpO2 93% on room air","correct":true},{"id":"s5","text":"Glucose 248 mg/dL","correct":true},{"id":"s6","text":"Creatinine 1.4 mg/dL","correct":true},{"id":"s7","text":"Triglycerides normal","correct":false},{"id":"s8","text":"Pain 9/10","correct":true}]}','RNMaster-Set24-Case','1'),
('Set24-RN-21','Physiological Adaptation','Case study: Analyze cues','matrix_grid','For each finding, indicate whether it primarily reflects fluid loss (third-spacing and vomiting) or a metabolic complication of pancreatitis. Metabolic','','','Fluid loss: hemoconcentration, prerenal azotemia, tachycardia/hypotension. Metabolic: hypocalcemia, hyperglycemia, perioral tingling. Pancreatic inflammation causes massive capillary leak into the abdomen. Fatty acids bind calcium (saponification), and damaged islet cells and stress hormones raise glucose.','Integrated','Adult Health','{"columns":[{"id":"c1","label":"Fluid loss"}],"rows":[{"id":"r1","label":"Hematocrit 50%","correct":"c1"},{"id":"r2","label":"BUN 34 mg/dL with creatinine rising","correct":"c1"},{"id":"r3","label":"HR 124/min with BP 94/58 mm Hg","correct":"c1"},{"id":"r4","label":"Calcium 7.6 mg/dL","correct":"c1"},{"id":"r5","label":"Glucose 248 mg/dL","correct":"c1"},{"id":"r6","label":"Tingling around the mouth","correct":"c1"}]}','RNMaster-Set24-Case','2'),
('Set24-RN-22','Physiological Adaptation','Case study: Prioritize hypotheses','cloze_dropdown','Complete the sentence by choosing from the lists of options. The client has ___1___, and the most immediate risk is ___2___.','','','shock from third-spacing A lipase more than three times normal with typical pain confirms pancreatitis, and heavy alcohol use is a leading cause. Early, adequate fluid resuscitation is key to preventing organ failure.','Integrated','Adult Health','{"blanks":[{"id":"b1","options":["acute pancreatitis, most likely alcohol-related","acute cholecystitis","a perforated peptic ulcer","acute myocardial infarction"],"correct":"acute pancreatitis, most likely alcohol-related"},{"id":"b2","options":["hypovolemic shock from third-spacing","fluid volume excess","hypoglycemia","hypercalcemia"],"correct":"hypovolemic shock from third-spacing"}]}','RNMaster-Set24-Case','3'),
('Set24-RN-23','Management of Care','Case study: Generate solutions','multiple_response','Which interventions does the nurse anticipate? Select all that apply. ☐','IV lactated Ringer''s with close monitoring of urine output and vital signs ☐|IV opioid analgesia such as hydromorphone ☐|Monitoring and replacement of calcium and monitoring of glucose ☐|Alcohol withdrawal monitoring with a CIWA-Ar protocol ☐|Advancing to oral or enteral feeding early as tolerated, rather than prolonged NPO ☐|Routine prophylactic antibiotics ☐|A high-fat diet to rest the pancreas','A,B,C,D,E','Current care emphasizes goal-directed fluid resuscitation (often with LR), adequate analgesia, electrolyte and glucose management, withdrawal monitoring, and early feeding when tolerated. Prophylactic antibiotics are not routinely recommended, and a low-fat diet is used when eating resumes.','Integrated','Management of Care','{}','RNMaster-Set24-Case','4'),
('Set24-RN-24','Physiological Adaptation','Case study: Take action','single_best_answer','Which prescription should the nurse implement first?','Lactated Ringer''s IV bolus|Obtain an abdominal CT scan|IV pantoprazole|Insert a nasogastric tube','A','Circulation is the immediate priority in a client with signs of hypovolemia. Imaging and other measures follow. NG tubes are used only for persistent vomiting or ileus.','Integrated','Adult Health','{}','RNMaster-Set24-Case','5'),
('Set24-RN-25','Physiological Adaptation','Case study: Evaluate outcomes','matrix_grid','Twenty-four hours later, the nurse reassesses the client. For each finding, indicate whether it shows improvement or requires immediate follow-up. Requires','','','Improved: vital signs, urine output, pain, BUN. Follow-up: worsening hypoxemia with bilateral infiltrates (possible ARDS), positive Trousseau''s sign (hypocalcemia). Improved hemodynamics, renal perfusion, and pain show response to treatment. Severe pancreatitis can trigger ARDS, and persistent hypocalcemia can cause tetany and dysrhythmias. Both require urgent intervention. Answers: Set 25: Mixed Review 8','Integrated','Adult Health','{"columns":[{"id":"c1","label":"Improved"}],"rows":[{"id":"r1","label":"HR 96/min, BP 118/72 mm Hg","correct":"c1"},{"id":"r2","label":"Urine output 50 mL/hr","correct":"c1"},{"id":"r3","label":"Pain 3/10","correct":"c1"},{"id":"r4","label":"BUN 22 mg/dL","correct":"c1"},{"id":"r5","label":"Carpal spasm when the BP cuff is inflated","correct":"c1"}]}','RNMaster-Set24-Case','6'),
('Set25-RN-20','Physiological Adaptation','Case study: Recognize cues','highlight','Highlight (circle) the findings that require immediate follow-up.','','','The client has a toxic ingestion with severe liver injury, coagulopathy, hypoglycemia, and hepatic encephalopathy, and has expressed a wish to die. SpO2 and temperature are acceptable.','Integrated','Adult Health','{"segments":[{"id":"s1","text":"\"I just wanted everything to stop\"","correct":false},{"id":"s2","text":"Oriented to person only with asterixis","correct":true},{"id":"s3","text":"Acetaminophen 180 mcg/mL at 18 hours","correct":true},{"id":"s4","text":"AST 4,200 and ALT 5,100 units/L","correct":false},{"id":"s5","text":"INR 3.2","correct":false},{"id":"s6","text":"Glucose 58 mg/dL","correct":true},{"id":"s7","text":"SpO2 97% on room air","correct":false},{"id":"s8","text":"Temperature 99.0°F","correct":false}]}','RNMaster-Set25-Case','1'),
('Set25-RN-21','Physiological Adaptation','Case study: Analyze cues','matrix_grid','For each finding, indicate whether it primarily reflects liver cell injury or loss of liver synthetic or metabolic function. Liver cell    Loss of liver Finding','','','Cell injury: AST, ALT, RUQ tenderness. Loss of function: INR (clotting factors), hypoglycemia (gluconeogenesis), ammonia and encephalopathy (detoxification). Transaminases leak from damaged hepatocytes. A rising INR, hypoglycemia, and encephalopathy indicate the liver is failing to make clotting factors, maintain glucose, and clear ammonia. These define acute liver failure.','Integrated','Adult Health','{"columns":[{"id":"c1","label":"function"}],"rows":[{"id":"r1","label":"AST 4,200 units/L","correct":"c1"},{"id":"r2","label":"ALT 5,100 units/L","correct":"c1"},{"id":"r3","label":"Right upper quadrant tenderness","correct":"c1"},{"id":"r4","label":"INR 3.2","correct":"c1"},{"id":"r5","label":"Glucose 58 mg/dL","correct":"c1"},{"id":"r6","label":"Elevated ammonia with confusion","correct":"c1"}]}','RNMaster-Set25-Case','2'),
('Set25-RN-22','Physiological Adaptation','Case study: Prioritize hypotheses','cloze_dropdown','Complete the sentence by choosing from the lists of options. The client has ___1___ and is at high risk for ___2___.','','','Coagulopathy increases bleeding risk. An intentional overdose indicates ongoing suicide risk.','Integrated','Adult Health','{"blanks":[{"id":"b1","options":["acute liver failure from acetaminophen overdose","viral gastroenteritis","acute cholecystitis","alcohol withdrawal"],"correct":"acute liver failure from acetaminophen overdose"},{"id":"b2","options":["cerebral edema, bleeding, and further suicide attempts","hypertension only","hypothermia","constipation"],"correct":"cerebral edema, bleeding, and further suicide attempts"}]}','RNMaster-Set25-Case','3'),
('Set25-RN-23','Management of Care','Case study: Generate solutions','multiple_response','Which interventions does the nurse anticipate? Select all that apply. ☐','IV acetylcysteine, even though more than 8 hours have passed ☐|A dextrose infusion with frequent glucose checks ☐|Frequent neurological assessments ☐|Bleeding precautions ☐|Continuous one-to-one observation for suicide risk ☐|Activated charcoal now ☐|Acetaminophen for the low-grade fever','A,B,C,D,E','Acetylcysteine benefits clients even with late presentation and established liver failure. Hypoglycemia, encephalopathy, and bleeding are managed and monitored, and early referral to a transplant center is common. Activated charcoal is not useful 18 hours after ingestion. Acetaminophen is contraindicated.','Integrated','Management of Care','{}','RNMaster-Set25-Case','4'),
('Set25-RN-24','Pharmacological and Parenteral Therapies','Case study: Take action','single_best_answer','Twenty minutes into the IV acetylcysteine loading dose, the client develops flushing and hives on the chest, without wheezing or hypotension. What should the nurse do?','Continue the infusion at the same rate|Pause the infusion, notify the provider, and anticipate an antihistamine and resuming at a slower rate|Permanently discontinue acetylcysteine|Administer epinephrine IM immediately','B','Anaphylactoid reactions to IV acetylcysteine are usually rate-related and occur most often during the loading dose. Mild reactions are managed by pausing, giving an antihistamine, and restarting more slowly, because the antidote is life-saving. Epinephrine is reserved for severe reactions.','Integrated','Pharmacology','{}','RNMaster-Set25-Case','5'),
('Set25-RN-25','Physiological Adaptation','Case study: Evaluate outcomes','matrix_grid','Forty-eight hours later, the nurse reassesses the client. For each finding, indicate whether it shows improvement or requires immediate follow-up. Requires','','','Improved: falling transaminases, INR 1.8, normal glucose, oriented. Follow-up: signs of rising ICP (cerebral edema), ongoing suicidal intent. Improving liver tests, clotting, glucose, and mentation show recovery. Cushing''s triad signs and pupil changes suggest cerebral edema, an emergency. A persistent statement of suicidal intent requires continued safety measures and psychiatric evaluation before discharge. Answers: Set 26: Mixed Review 9','Integrated','Adult Health','{"columns":[{"id":"c1","label":"Improved"}],"rows":[{"id":"r1","label":"AST and ALT decreasing","correct":"c1"},{"id":"r2","label":"INR 1.8","correct":"c1"},{"id":"r3","label":"Glucose 98 mg/dL","correct":"c1"},{"id":"r4","label":"Oriented to person, place, and time","correct":"c1"},{"id":"r5","label":"Client says, \"I''ll just do it again when I get home\"","correct":"c1"}]}','RNMaster-Set25-Case','6'),
('Set26-RN-20','Physiological Adaptation','Case study: Recognize cues','highlight','Highlight (circle) the findings that require immediate follow-up.','','','Bronchorrhea and bronchospasm threaten the airway, and bradycardia and hypotension reflect cholinergic excess. Fasciculations signal a risk of respiratory muscle weakness. Contaminated clothing is an ongoing exposure risk for the client and staff.','Integrated','Adult Health','{"segments":[{"id":"s1","text":"Copious, bubbling airway secretions with wheezing","correct":true},{"id":"s2","text":"SpO2 86% on room air","correct":true},{"id":"s3","text":"HR 44/min","correct":false},{"id":"s4","text":"BP 92/56 mm Hg","correct":false},{"id":"s5","text":"Muscle twitching","correct":true},{"id":"s6","text":"Intermittent confusion","correct":true},{"id":"s7","text":"Damp clothing with a chemical odor","correct":true},{"id":"s8","text":"Temperature 98.8°F","correct":false}]}','RNMaster-Set26-Case','1'),
('Set26-RN-21','Physiological Adaptation','Case study: Analyze cues','matrix_grid','For each finding, indicate whether it primarily reflects muscarinic or nicotinic receptor overstimulation.','','','Muscarinic: secretions, bronchorrhea, miosis, bradycardia. Nicotinic: fasciculations, weakness. Organophosphates inhibit acetylcholinesterase, causing acetylcholine to accumulate. Muscarinic effects follow the "DUMBELS" mnemonic (Diarrhea, Urination, Miosis, Bronchorrhea/Bradycardia, Emesis, Lacrimation, Salivation). Nicotinic effects at the neuromuscular junction cause twitching, then weakness and paralysis.','Integrated','Adult Health','{"columns":[{"id":"c1","label":"Muscarinic"},{"id":"c2","label":"Nicotinic"}],"rows":[{"id":"r1","label":"Excessive salivation and tearing","correct":"c1"},{"id":"r2","label":"Bronchial secretions and wheezing","correct":"c1"},{"id":"r3","label":"Pinpoint pupils","correct":"c1"},{"id":"r4","label":"Bradycardia","correct":"c1"},{"id":"r5","label":"Muscle fasciculations","correct":"c1"},{"id":"r6","label":"Muscle weakness","correct":"c1"}]}','RNMaster-Set26-Case','2'),
('Set26-RN-22','Physiological Adaptation','Case study: Prioritize hypotheses','cloze_dropdown','Complete the sentence by choosing from the lists of options. The client is experiencing ___1___, and the greatest threat to life is ___2___.','','','failure from secretions, bronchospasm, and muscle weakness Pinpoint pupils occur with both opioids and organophosphates, but copious secretions, sweating, and fasciculations point to cholinergic toxicity. Anticholinergic toxicity causes dry skin and dilated pupils. Respiratory failure is the leading cause of death.','Integrated','Adult Health','{"blanks":[{"id":"b1","options":["organophosphate (cholinergic) poisoning","anticholinergic toxicity","opioid overdose","heat stroke"],"correct":"organophosphate (cholinergic) poisoning"},{"id":"b2","options":["respiratory failure from secretions, bronchospasm, and muscle weakness","hyperthermia","hypoglycemia","kidney stones"],"correct":"respiratory failure from secretions, bronchospasm, and muscle weakness"}]}','RNMaster-Set26-Case','3'),
('Set26-RN-23','Pharmacological and Parenteral Therapies','Case study: Generate solutions','multiple_response','Which interventions does the nurse anticipate? Select all that apply. ☐','Remove and bag contaminated clothing and wash the skin with soap and water, with staff wearing appropriate PPE ☐|IV atropine, repeated until airway secretions dry ☐|IV pralidoxime ☐|High-flow oxygen, airway suctioning, and preparation for intubation ☐|A benzodiazepine for seizures if they occur ☐|IV physostigmine ☐|Allowing staff to handle the clothing without gloves','A,B,C,D,E','Decontamination protects the client and staff. Atropine blocks muscarinic effects, with drying of secretions as the endpoint. Pralidoxime reactivates acetylcholinesterase and helps nicotinic weakness. Airway support and seizure control are essential. Physostigmine increases acetylcholine and would worsen toxicity.','Integrated','Pharmacology','{}','RNMaster-Set26-Case','4'),
('Set26-RN-24','Safety and Infection Control','Case study: Take action','single_best_answer','As the client arrives in the emergency department, what should the nurse do first?','Begin physical assessment without PPE to save time|Put on appropriate PPE before contact with the client or contaminated clothing|Obtain a detailed history of the chemical|Start an IV in the triage area with staff not wearing gloves','B','Staff can be poisoned by secondary exposure. PPE is put on first, then airway management and decontamination proceed together, ideally in a designated area.','Integrated','Safety & Infection Control','{}','RNMaster-Set26-Case','5'),
('Set26-RN-25','Physiological Adaptation','Case study: Evaluate outcomes','matrix_grid','After several doses of atropine and pralidoxime, the nurse reassesses the client. For each finding, indicate whether it shows effective treatment or requires follow-up. Requires','','','Effective: dry secretions, HR 96, SpO2 95%, resolved GI symptoms. Follow-up: delayed proximal weakness (intermediate syndrome), signs of atropine toxicity. Drying of secretions is the key atropine endpoint. Proximal weakness 1–4 days later may indicate intermediate syndrome, which can cause respiratory failure. Hyperthermia, delirium, and ileus suggest excessive atropine, requiring dose adjustment. Answers: Set 27: Mixed Review 10','Integrated','Adult Health','{"columns":[{"id":"c1","label":"Effective"}],"rows":[{"id":"r1","label":"Lungs clear with dry airway secretions","correct":"c1"},{"id":"r2","label":"HR 96/min","correct":"c1"},{"id":"r3","label":"SpO2 95% on oxygen","correct":"c1"},{"id":"r4","label":"No further vomiting or diarrhea","correct":"c1"}]}','RNMaster-Set26-Case','6'),
('Set27-RN-20','Physiological Adaptation','Case study: Recognize cues','highlight','Highlight (circle) the findings that require immediate follow-up.','','','Hyperthermia, rapid dysrhythmia, CNS dysfunction, and fluid losses are signs of life-threatening decompensation. Exophthalmos, pretibial myxedema, and goiter are chronic features of Graves'' disease.','Integrated','Adult Health','{"segments":[{"id":"s1","text":"T 104.9°F (40.5°C)","correct":false},{"id":"s2","text":"HR 168/min in atrial fibrillation","correct":false},{"id":"s3","text":"Agitation and disorientation","correct":true},{"id":"s4","text":"Several loose stools daily with profuse sweating","correct":false},{"id":"s5","text":"SpO2 93% on room air","correct":true},{"id":"s6","text":"Exophthalmos","correct":false},{"id":"s7","text":"Thickened skin on the shins","correct":false},{"id":"s8","text":"Enlarged thyroid with a bruit","correct":true}]}','RNMaster-Set27-Case','1'),
('Set27-RN-21','Physiological Adaptation','Case study: Analyze cues','matrix_grid','For each finding, indicate whether it is a chronic feature of Graves'' disease or a sign of acute decompensation (thyroid storm). Chronic Acute decomp','','','Chronic: exophthalmos, goiter with bruit, pretibial myxedema. Acute: hyperthermia, delirium, AF with RVR. Thyroid storm is distinguished from uncomplicated hyperthyroidism by severe hyperthermia, cardiovascular dysfunction, CNS changes, and GI or hepatic dysfunction. Scoring systems such as the Burch-Wartofsky scale use these features.','Integrated','Adult Health','{"columns":[{"id":"c1","label":"Graves''"}],"rows":[{"id":"r1","label":"Exophthalmos","correct":"c1"},{"id":"r2","label":"Enlarged thyroid with a bruit","correct":"c1"},{"id":"r3","label":"Thickened skin on the shins (pretibial myxedema)","correct":"c1"},{"id":"r4","label":"Temperature of 104.9°F","correct":"c1"},{"id":"r5","label":"Delirium","correct":"c1"},{"id":"r6","label":"Atrial fibrillation with rapid ventricular rate","correct":"c1"}]}','RNMaster-Set27-Case','2'),
('Set27-RN-22','Physiological Adaptation','Case study: Prioritize hypotheses','cloze_dropdown','Complete the sentence by choosing from the lists of options. The client is experiencing ___1___, precipitated by ___2___.','','','and stopping antithyroid medication Infection, surgery, trauma, and stopping antithyroid drugs are common triggers. Myxedema coma is the opposite (hypothermia and bradycardia). There is no antipsychotic or alcohol history.','Integrated','Adult Health','{"blanks":[{"id":"b1","options":["thyroid storm","myxedema coma","neuroleptic malignant syndrome","alcohol withdrawal"],"correct":"thyroid storm"},{"id":"b2","options":["pneumonia and stopping antithyroid medication","excess levothyroxine intake only","an antipsychotic medication","hypoglycemia"],"correct":"pneumonia and stopping antithyroid medication"}]}','RNMaster-Set27-Case','3'),
('Set27-RN-23','Pharmacological and Parenteral Therapies','Case study: Generate solutions','multiple_response','Which interventions does the nurse anticipate? Select all that apply. ☐','Propranolol to control heart rate and adrenergic symptoms ☐|Propylthiouracil (or methimazole) to block new hormone synthesis ☐|IV hydrocortisone ☐|Acetaminophen and external cooling measures ☐|IV fluids and antibiotics for pneumonia ☐|Aspirin for fever ☐|Levothyroxine','A,B,C,D,E','Thyroid storm treatment includes beta blockade, thionamides, iodine given after the thionamide, corticosteroids (which reduce T4-to-T3 conversion and treat possible adrenal insufficiency), cooling, fluids, and treating the trigger. Aspirin displaces thyroid hormone from binding proteins and increases free hormone. Levothyroxine would worsen the condition.','Integrated','Pharmacology','{}','RNMaster-Set27-Case','4'),
('Set27-RN-24','Pharmacological and Parenteral Therapies','Case study: Take action','single_best_answer','The nurse has prescriptions for propylthiouracil (PTU) and potassium iodide. How should these be timed?','Give potassium iodide first, then PTU the next day|Give PTU first, then give potassium iodide at least 1 hour later|Give both at the same time|Give only potassium iodide','B','Iodine given before a thionamide can serve as substrate for new hormone synthesis and worsen thyrotoxicosis. PTU blocks synthesis first, and iodine then blocks hormone release.','Integrated','Pharmacology','{}','RNMaster-Set27-Case','5'),
('Set27-RN-25','Physiological Adaptation','Case study: Evaluate outcomes','matrix_grid','Over the following days, the nurse reassesses the client. For each finding, indicate whether it shows improvement or requires immediate follow-up. Requires','','','Improved: temperature, HR in sinus rhythm, orientation, BP. Follow-up: agranulocytosis (sore throat, fever, low ANC), hepatotoxicity (jaundice, rising liver enzymes). Normalizing vital signs and mental status show response. Thionamides can cause agranulocytosis, and PTU carries a boxed warning for severe liver injury. Both require stopping the drug and immediate provider notification. Answers: Set 28: Mixed Review 11','Integrated','Adult Health','{"columns":[{"id":"c1","label":"Improved"}],"rows":[{"id":"r1","label":"T 99.8°F (37.7°C)","correct":"c1"},{"id":"r2","label":"HR 92/min in sinus rhythm","correct":"c1"},{"id":"r3","label":"Oriented to person, place, and time","correct":"c1"},{"id":"r4","label":"BP 128/76 mm Hg","correct":"c1"},{"id":"r5","label":"Jaundice with rising AST and ALT","correct":"c1"}]}','RNMaster-Set27-Case','6'),
('Set28-RN-20','Physiological Adaptation','Case study: Recognize cues','highlight','Highlight (circle) the findings that require immediate follow-up.','','','function. Decreased responsiveness suggests hypoxic effects. Hypothermia and wet clothing need prompt correction. Sodium and BP are acceptable.','Integrated','Adult Health','{"segments":[{"id":"s1","text":"SpO2 89% on room air","correct":true},{"id":"s2","text":"RR 44/min with retractions","correct":true},{"id":"s3","text":"Crackles with frothy, pink-tinged sputum","correct":true},{"id":"s4","text":"Drowsy but responds to voice","correct":false},{"id":"s5","text":"Temperature 95.0°F (35.0°C)","correct":false},{"id":"s6","text":"Wet clothing","correct":true},{"id":"s7","text":"Sodium 138 mEq/L","correct":false},{"id":"s8","text":"BP 92/58 mm Hg","correct":false}]}','RNMaster-Set28-Case','1'),
('Set28-RN-21','Physiological Adaptation','Case study: Analyze cues','matrix_grid','For each finding, indicate whether it primarily reflects lung injury from aspiration or hypothermia. Lung injury/hy','','','Lung injury: crackles/frothy sputum, hypoxemia, increased work of breathing. Hypothermia: low core temperature, shivering, cool mottled skin. Aspirated water washes out surfactant and causes alveolar collapse and pulmonary edema. Immersion and wet clothing cause heat loss. Both require treatment.','Integrated','Adult Health','{"columns":[{"id":"c1","label":"Hypothermia"}],"rows":[{"id":"r1","label":"Crackles and frothy sputum","correct":"c1"},{"id":"r2","label":"SpO2 89% on room air","correct":"c1"},{"id":"r3","label":"Retractions with tachypnea","correct":"c1"},{"id":"r4","label":"Core temperature of 95.0°F","correct":"c1"},{"id":"r5","label":"Shivering","correct":"c1"},{"id":"r6","label":"Cool, mottled extremities","correct":"c1"}]}','RNMaster-Set28-Case','2'),
('Set28-RN-22','Physiological Adaptation','Case study: Prioritize hypotheses','cloze_dropdown','Complete the sentence by choosing from the lists of options. The child experienced ___1___ and is at risk for ___2___ over the next several hours.','','','respiratory failure (such as ARDS) Respiratory symptoms after drowning can worsen over hours as lung injury progresses. Symptomatic children are observed closely and admitted for monitoring.','Integrated','Adult Health','{"blanks":[{"id":"b1","options":["a drowning event with aspiration-related lung injury and hypothermia","a simple choking episode","an asthma attack","a febrile seizure"],"correct":"a drowning event with aspiration-related lung injury and hypothermia"},{"id":"b2","options":["worsening respiratory failure (such as ARDS)","hyperthermia","hypoglycemia only","constipation"],"correct":"worsening respiratory failure (such as ARDS)"}]}','RNMaster-Set28-Case','3'),
('Set28-RN-23','Management of Care','Case study: Generate solutions','multiple_response','Which interventions does the nurse anticipate? Select all that apply. ☐','High-flow oxygen with preparation for CPAP or other ventilatory support ☐|Removing wet clothing and actively rewarming ☐|Continuous cardiorespiratory monitoring and pulse oximetry ☐|Frequent neurological assessments ☐|Monitoring glucose and electrolytes ☐|Abdominal thrusts to remove water from the lungs ☐|Routine prophylactic antibiotics for all drowning victims','A,B,C,D,E','Care focuses on oxygenation, rewarming, and monitoring for deterioration. Abdominal thrusts do not remove water from the lungs and can cause vomiting and aspiration. Antibiotics are given only for signs of infection or grossly contaminated water.','Integrated','Management of Care','{}','RNMaster-Set28-Case','4'),
('Set28-RN-24','Physiological Adaptation','Case study: Take action','single_best_answer','Which action should the nurse take first?','Remove the child''s wet clothing|Apply high-flow oxygen by nonrebreather mask|Obtain a repeat chest x-ray|Perform abdominal thrusts','B','Hypoxemia is the most immediate threat, so oxygen comes first. Removing wet clothing and rewarming follow right away and are often done simultaneously by the team.','Integrated','Adult Health','{}','RNMaster-Set28-Case','5'),
('Set28-RN-25','Physiological Adaptation','Case study: Evaluate outcomes','matrix_grid','The nurse evaluates the child over the next several hours. For each finding, indicate whether it shows improvement or requires follow-up. Requires','','','Improved: oxygenation, normothermia, alert, normal RR at 2 hours. Follow-up: delayed respiratory deterioration at 6 hours; parent needs water safety teaching. Initial improvement can be followed by delayed pulmonary edema, which is why observation continues. Drowning prevention teaching includes constant, close supervision, four-sided pool fencing, and CPR training for caregivers. Answers: Set 29: Mixed Review 12','Integrated','Adult Health','{"columns":[{"id":"c1","label":"Improved"}],"rows":[{"id":"r1","label":"SpO2 97% on 2 L/min nasal cannula at 2 hours","correct":"c1"},{"id":"r2","label":"Temperature 98.2°F (36.8°C)","correct":"c1"},{"id":"r3","label":"Alert and playful","correct":"c1"},{"id":"r4","label":"RR 28/min without retractions at 2 hours","correct":"c1"},{"id":"r5","label":"At 6 hours: RR 56/min, new retractions, and SpO2 decreasing","correct":"c1"}]}','RNMaster-Set28-Case','6'),
('Set29-RN-20','Physiological Adaptation','Case study: Recognize cues','highlight','Highlight (circle) the findings that require immediate follow-up.','','','Pain, pallor, pulselessness, paresthesia, paralysis, and coldness (the 6 P''s) indicate acute arterial occlusion. Sensory and motor loss mean the limb is threatened. AF without anticoagulation is the likely embolic source.','Integrated','Adult Health','{"segments":[{"id":"s1","text":"Pale, cold left foot and lower leg","correct":true},{"id":"s2","text":"Absent pulses with no Doppler signal","correct":true},{"id":"s3","text":"Numbness of the left toes","correct":true},{"id":"s4","text":"Weak dorsiflexion of the left foot","correct":true},{"id":"s5","text":"HR 112/min and irregularly irregular","correct":false},{"id":"s6","text":"Stopped apixaban 3 weeks ago","correct":true},{"id":"s7","text":"Right leg warm with palpable pulses","correct":true},{"id":"s8","text":"SpO2 97% on room air","correct":false}]}','RNMaster-Set29-Case','1'),
('Set29-RN-21','Physiological Adaptation','Case study: Analyze cues','matrix_grid','For each finding, indicate whether it is more consistent with acute arterial occlusion or deep vein thrombosis. Acute arterial   Deep vein Finding','','','Arterial: pale cold limb, absent pulses, neuro deficits, sudden onset with AF. DVT: warm red swollen calf, pitting edema. Arterial occlusion blocks inflow, so the limb is cold, pale, and pulseless. DVT blocks venous outflow, causing a warm, swollen, congested limb with intact pulses. Positioning and treatment differ for each.','Integrated','Adult Health','{"columns":[{"id":"c1","label":"thrombosis"}],"rows":[{"id":"r1","label":"Pale, cold extremity","correct":"c1"},{"id":"r2","label":"Absent distal pulses","correct":"c1"},{"id":"r3","label":"Numbness and weakness","correct":"c1"},{"id":"r4","label":"Warm, red, swollen calf","correct":"c1"},{"id":"r5","label":"Pitting edema of the lower leg","correct":"c1"}]}','RNMaster-Set29-Case','2'),
('Set29-RN-22','Physiological Adaptation','Case study: Prioritize hypotheses','cloze_dropdown','Complete the sentence by choosing from the lists of options. The client has ___1___, and without prompt treatment is at risk for ___2___.','','','Skeletal muscle and nerves tolerate ischemia for only about 4–6 hours before permanent damage occurs.','Integrated','Adult Health','{"blanks":[{"id":"b1","options":["acute limb ischemia from an arterial embolism related to atrial fibrillation","a deep vein thrombosis","cellulitis","lumbar spinal stenosis"],"correct":"acute limb ischemia from an arterial embolism related to atrial fibrillation"},{"id":"b2","options":["irreversible tissue damage and limb loss within hours","varicose veins","lymphedema","a muscle strain"],"correct":"irreversible tissue damage and limb loss within hours"}]}','RNMaster-Set29-Case','3'),
('Set29-RN-23','Management of Care','Case study: Generate solutions','multiple_response','Which interventions does the nurse anticipate? Select all that apply. ☐','IV heparin bolus and infusion as prescribed ☐|Preparation for emergency revascularization, such as embolectomy or catheter-directed therapy ☐|Keep the affected leg level or slightly dependent ☐|Protect the limb from pressure and injury, with no heat applied ☐|Frequent neurovascular checks of both legs ☐|Elevate the affected leg above heart level ☐|Apply a heating pad to warm the foot','A,B,C,D,E','Heparin prevents clot extension, and urgent revascularization restores flow. A level or slightly dependent position helps arterial flow. Heat can burn ischemic tissue and increases metabolic demand. Elevation reduces arterial perfusion.','Integrated','Management of Care','{}','RNMaster-Set29-Case','4'),
('Set29-RN-24','Management of Care','Case study: Take action','single_best_answer','What is the nurse''s priority action?','Apply a warm compress to the left leg|Elevate the left leg on pillows|Notify the provider immediately so emergency revascularization can be arranged|Encourage the client to walk to improve circulation','C','Acute limb ischemia with sensory and motor deficits is a vascular emergency. Time to revascularization determines whether the limb can be saved.','Integrated','Management of Care','{}','RNMaster-Set29-Case','5'),
('Set29-RN-25','Physiological Adaptation','Case study: Evaluate outcomes','matrix_grid','After surgical embolectomy, the nurse monitors the client. For each finding, indicate whether it shows effective treatment or requires immediate follow-up. Requires','','','Effective: pulse restored, warm pink foot, brisk capillary refill, sensation returned. Follow-up: reperfusion compartment syndrome; rhabdomyolysis with myoglobinuria. Restored perfusion shows success. Reperfusion can cause muscle swelling and compartment syndrome, which may require fasciotomy. Myoglobin released from damaged muscle can cause acute kidney injury, so aggressive IV fluids and monitoring are needed. Answers: Set 30: Mixed Review 13','Integrated','Adult Health','{"columns":[{"id":"c1","label":"Effective"}],"rows":[{"id":"r1","label":"Palpable left dorsalis pedis pulse","correct":"c1"},{"id":"r2","label":"Left foot warm and pink","correct":"c1"},{"id":"r3","label":"Capillary refill under 3 seconds","correct":"c1"},{"id":"r4","label":"Sensation returned to the left toes","correct":"c1"},{"id":"r5","label":"Dark, tea-colored urine with CK 18,000 units/L","correct":"c1"}]}','RNMaster-Set29-Case','6'),
('Set30-RN-20','Physiological Adaptation','Case study: Recognize cues','highlight','Highlight (circle) the 1030 findings that require immediate follow-up.','','','Sudden relief of appendicitis pain followed by diffuse rigidity suggests perforation. Fever, tachycardia, hypotension, lethargy, and poor perfusion indicate peritonitis with septic shock. Hypotension is a late sign in children.','Integrated','Adult Health','{"segments":[{"id":"s1","text":"\"My tummy suddenly feels better\"","correct":false},{"id":"s2","text":"Diffusely rigid, distended abdomen","correct":true},{"id":"s3","text":"Absent bowel sounds","correct":true},{"id":"s4","text":"Lethargy","correct":true},{"id":"s5","text":"T 103.3°F (39.6°C)","correct":false},{"id":"s6","text":"HR 146/min with BP 86/50 mm Hg","correct":true},{"id":"s7","text":"Capillary refill 4 seconds","correct":true},{"id":"s8","text":"NPO with IV fluids running","correct":true}]}','RNMaster-Set30-Case','1'),
('Set30-RN-21','Physiological Adaptation','Case study: Analyze cues','matrix_grid','For each finding, indicate whether it is more consistent with uncomplicated appendicitis or perforation with peritonitis. Uncomplicate     Perforation/pe Finding','','','Uncomplicated: migrating pain, localized rebound tenderness, anorexia and vomiting. Perforation: sudden pain relief, diffuse rigidity with absent bowel sounds, sepsis signs. Perforation releases pressure, briefly relieving pain, then spreads infection throughout the peritoneum. Younger children perforate more often because symptoms are harder to recognize.','Integrated','Adult Health','{"columns":[{"id":"c1","label":"ritonitis"}],"rows":[{"id":"r1","label":"Pain migrating from the umbilicus to the right lower quadrant","correct":"c1"},{"id":"r2","label":"Rebound tenderness at McBurney''s point","correct":"c1"},{"id":"r3","label":"Loss of appetite and vomiting","correct":"c1"},{"id":"r4","label":"Sudden relief of pain","correct":"c1"},{"id":"r5","label":"Diffusely rigid abdomen with absent bowel sounds","correct":"c1"},{"id":"r6","label":"High fever with tachycardia and hypotension","correct":"c1"}]}','RNMaster-Set30-Case','2'),
('Set30-RN-22','Physiological Adaptation','Case study: Prioritize hypotheses','cloze_dropdown','Complete the sentence by choosing from the lists of options. The child is most likely experiencing ___1___ with ___2___.','','','shock Pain relief does not mean the appendicitis has resolved when it is followed by worsening abdominal and systemic findings. Hypotension with poor perfusion in a febrile child indicates septic shock.','Integrated','Adult Health','{"blanks":[{"id":"b1","options":["a ruptured appendix with peritonitis","resolution of appendicitis","gastroenteritis","intussusception"],"correct":"a ruptured appendix with peritonitis"},{"id":"b2","options":["septic shock","dehydration only","anxiety","a normal fever response"],"correct":"septic shock"}]}','RNMaster-Set30-Case','3'),
('Set30-RN-23','Management of Care','Case study: Generate solutions','multiple_response','Which interventions does the nurse anticipate? Select all that apply. ☐','Keep the child NPO ☐|Isotonic IV fluid bolus of 20 mL/kg with reassessment ☐|Broad-spectrum IV antibiotics ☐|IV analgesia, such as morphine ☐|Preparation for emergency surgery ☐|A heating pad on the abdomen ☐|A laxative or enema','A,B,C,D,E','Perforated appendicitis requires resuscitation, antibiotics, pain control, and surgery. Heat and laxatives or enemas can spread infection and are contraindicated. Analgesia does not mask the diagnosis enough to justify withholding it.','Integrated','Management of Care','{}','RNMaster-Set30-Case','4'),
('Set30-RN-24','Management of Care','Case study: Take action','single_best_answer','At 1030, when the child reports suddenly feeling better and then becomes lethargic with a rigid abdomen, what should the nurse do first?','Document the pain improvement and continue routine care|Offer clear liquids now that the pain is better|Notify the surgeon and provider immediately and call for rapid response|Apply a warm pack to the abdomen','C','Signs of perforation and shock require immediate escalation for resuscitation and emergency surgery. The child remains NPO.','Integrated','Management of Care','{}','RNMaster-Set30-Case','5'),
('Set30-RN-25','Physiological Adaptation','Case study: Evaluate outcomes','matrix_grid','After appendectomy and antibiotic therapy, the nurse evaluates the child. For each finding, indicate whether it shows expected recovery or requires follow-up. Expected   Requires Finding','','','Expected: afebrile, advancing diet, ambulating, controlled pain. Follow-up: surgical site infection; possible intra-abdominal (pelvic) abscess. Perforated appendicitis carries a higher risk of wound infection and abscess. New fever, pain, and diarrhea after initial improvement suggest a pelvic abscess needing imaging and possible drainage. Answers: Set 31: Mixed Review 14','Integrated','Adult Health','{"columns":[{"id":"c1","label":"follow-up"}],"rows":[{"id":"r1","label":"Afebrile on postoperative day 3","correct":"c1"},{"id":"r2","label":"Tolerating clear liquids and advancing diet","correct":"c1"},{"id":"r3","label":"Walking in the hallway","correct":"c1"},{"id":"r4","label":"Pain 2/10 with oral medication","correct":"c1"},{"id":"r5","label":"Incision red, warm, and draining thick yellow fluid","correct":"c1"},{"id":"r6","label":"Day 5: new fever of 102.2°F (39°C), pelvic pain, and diarrhea","correct":"c1"}]}','RNMaster-Set30-Case','6')
) x(src,client_need,topic,item_type,stem,opts,keys,rationale,body_system,discipline,response_config,caseid,case_sequence) loop
 qid:=md5('rnmaster-'||lower(r.src))::uuid; qvid:=md5('rnmaster-v-'||lower(r.src))::uuid;
 insert into public.questions(id,slug,lifecycle_status,current_version) values(qid,'rnmaster-'||lower(r.src),'pilot',1) on conflict(slug) do update set updated_at=now() returning id into qid;
 insert into public.question_versions(id,question_id,version,stem,item_type,exam_tracks,subject,topic,client_need,difficulty,rationale_correct,rationale_distractors,memory_rule,source_note,validation_status,professional_role_focus,track_rationale,body_system,discipline,source_id,response_config,scoring_method,case_set_id,case_study_id,case_sequence) values(qvid,qid,1,r.stem,r.item_type,array['rn'],r.client_need,r.topic,r.client_need,'medium',r.rationale,'Evaluate each response against the source key and clinical task.','Interpret the case cues and respond in the native NCLEX item format.','User-provided NCLEX-RN Master Edition; loaded as PILOT pending clinical/editorial validation. Not human or psychometrically validated.','pilot','Entry-level RN clinical judgment.','NCLEX-RN',r.body_system,r.discipline,'RNMaster-'||r.src,r.response_config::jsonb,case when r.item_type='multiple_response' then 'plus_minus' when r.item_type='single_best_answer' then 'zero_one' else r.item_type end,nullif(r.caseid,''),nullif(r.caseid,''),case when r.case_sequence::int>0 then r.case_sequence::int else null end) on conflict(question_id,version) do update set stem=excluded.stem,item_type=excluded.item_type,response_config=excluded.response_config,source_id=excluded.source_id,case_set_id=excluded.case_set_id,case_study_id=excluded.case_study_id,case_sequence=excluded.case_sequence,validation_status='pilot' returning id into qvid;
 delete from public.question_options where question_version_id=qvid;
 if r.item_type in ('single_best_answer','multiple_response') then keyarr:=string_to_array(r.keys,','); n:=0; for optrec in select unnest(string_to_array(r.opts,'|')) as txt loop n:=n+1; insert into public.question_options(question_version_id,option_key,option_text,is_correct,rationale,display_order) values(qvid,chr(96+n),optrec.txt,(upper(chr(96+n))=any(keyarr)),case when upper(chr(96+n))=any(keyarr) then r.rationale else null end,n); end loop; select count(*) filter(where is_correct) into kc from public.question_options where question_version_id=qvid; if (r.item_type='single_best_answer' and kc<>1) or (r.item_type='multiple_response' and kc<2) then raise exception 'Key integrity failed %',r.src; end if; end if;
 update public.question_versions set key_consistency_status='pass',key_consistency_checked_at=now(),key_consistency_notes='Source answer mapped to native response model; clinical review pending.' where id=qvid;
end loop; end $$; commit;